<script setup lang="ts">
const route=useRoute(),password=ref(''),confirm=ref(''),loading=ref(false),done=ref(false),error=ref('');async function submit(){if(password.value!==confirm.value){error.value='Les mots de passe ne correspondent pas';return}loading.value=true;try{await $fetch('/api/auth/reset-password',{method:'POST',body:{token:route.query.token,password:password.value}});done.value=true}catch(e:any){error.value=e?.data?.statusMessage||'Lien invalide'}finally{loading.value=false}};useSeoMeta({title:'Nouveau mot de passe'})
</script><template><main class="auth-page page-top"><section class="auth-card"><p class="eyebrow">SÉCURITÉ</p><h1>Nouveau mot de passe.</h1><div v-if="done" class="auth-success"><AppIcon name="check"/><strong>Mot de passe modifié</strong><NuxtLink class="btn btn--primary" to="/login">Se connecter</NuxtLink></div><form v-else @submit.prevent="submit"><label>Nouveau mot de passe<input v-model="password" type="password" minlength="10" required></label><label>Confirmation<input v-model="confirm" type="password" required></label><p v-if="error" class="auth-error">{{ error }}</p><button class="btn btn--primary" :disabled="loading">{{ loading?'Modification…':'Enregistrer' }}</button></form></section></main></template>
